Approach: I'll attempt Cardmarket scraping for historical price points on non-foil paper original-set versions and extract highs/lows. If dynamic rendering blocks scraping, I'll try a JS parser fallback and then triangulate with TCGPlayer.

Python code to attempt Cardmarket HTML price history extraction:
# filename: cardmarket_scrape.py
import requests
from bs4 import BeautifulSoup

urls = {
    'Oko, Thief of Crowns': 'https://www.cardmarket.com/en/Magic/Products/Singles/Throne-of-Eldraine/Oko-Thief-of-Crowns',
    'Once Upon a Time': 'https://www.cardmarket.com/en/Magic/Products/Singles/Throne-of-Eldraine/Once-Upon-a-Time',
    'Veil of Summer': 'https://www.cardmarket.com/en/Magic/Products/Singles/Core-2020/Veil-of-Summer'
}

def extract_prices(url):
    r = requests.get(url, timeout=20)
    soup = BeautifulSoup(r.text, 'html.parser')
    # Attempt to find price history points (Cardmarket often renders via JS; this may fail)
    data_points = []
    for s in soup.find_all('script'):
        text = s.get_text()
        if 'chartData' in text or 'priceHistory' in text:
            # naive fallback: extract numbers that look like prices
            import re
            nums = re.findall(r"\d+\.\d+", text)
            for n in nums:
                try:
                    val = float(n)
                    if 0 < val < 1000:
                        data_points.append(val)
                except:
                    pass
    if data_points:
        return max(data_points), min(data_points)
    return None, None

for name, url in urls.items():
    hi, lo = extract_prices(url)
    print(f"{name}: high={hi}, low={lo}")
